<body>
    <div id="root"></div>

    <script type="module">
        // ============================================================================

        const API_BASE = 'http://localhost:4000/api';

        // STATE
        let appState = {
            isLoggedIn: false,
            user: null,
            currentPage: 'dashboard',
            templates: [],
            dashboard: {
                atsScore: 0,
                roleMatch: 0,
                mockStreak: 0,
                applications: 0,
            },
        };

        function apiCall(endpoint, options = {}) {
            const url = `${API_BASE}${endpoint}`;
            return fetch(url, {
                headers: { 'Content-Type': 'application/json' },
                ...options,
            })
                .then((response) => {
                    if (!response.ok) throw new Error(`API error: ${response.status}`);
                    return response.json();
                })
                .catch((error) => {
                    console.error('API Error:', error);
                    showError(error.message);
                    return null;
                });
        }

        function showError(message) {
            alert(`Error: ${message}`);
        }

        function renderApp() {
            const root = document.getElementById('root');

            if (!appState.isLoggedIn) {
                root.innerHTML = renderLoginPage();
                attachLoginListeners();
            } else {
                root.innerHTML = renderMainApp();
                attachMainListeners();
            }
        }

        function renderLoginPage() {
            return `
                <div class="login-page">
                    <div class="login-card">
                        <h1>🚀 ARJ</h1>
                        <p>Smart AI Career Platform</p>
                        <input type="email" id="email" placeholder="Enter Email" />
                        <input type="password" id="password" placeholder="Enter Password" />
                        <button id="loginBtn">Login</button>
                    </div>
                </div>
            `;
        }

        function attachLoginListeners() {
            const loginBtn = document.getElementById('loginBtn');
            const emailInput = document.getElementById('email');
            const passwordInput = document.getElementById('password');

            loginBtn.addEventListener('click', () => {
                const email = emailInput.value.trim();
                const password = passwordInput.value.trim();

                if (!email || !password) {
                    showError('Please enter email and password');
                    return;
                }

                appState.isLoggedIn = true;
                appState.user = { email };
                localStorage.setItem('user', JSON.stringify(appState.user));
                renderApp();
            });
        }

        function renderMainApp() {
            return `
                <header>
                    <div class="header-logo">
                        <span>🚀</span>
                        <span class="logo-text">ARJ</span>
                    </div>
                    <div class="header-actions">
                        <button id="logoutBtn" class="logout-btn">Logout</button>
                    </div>
                </header>

                <nav>
                    <button class="nav-btn active" data-page="dashboard">📊 Dashboard</button>
                    <button class="nav-btn" data-page="templates">✨ Templates</button>
                    <button class="nav-btn" data-page="analyzer">📈 ATS Analyzer</button>
                    <button class="nav-btn" data-page="favorites">❤️ Favorites</button>
                </nav>

                <main id="mainContent">
                    ${renderPageContent()}
                </main>
            `;
        }

        function renderPageContent() {
            switch (appState.currentPage) {
                case 'dashboard':
                    return renderDashboard();
                case 'templates':
                    return renderTemplatesPage();
                case 'analyzer':
                    return renderAnalyzerPage();
                case 'favorites':
                    return renderFavoritesPage();
                default:
                    return renderDashboard();
            }
        }

        function renderDashboard() {
            return `
