                    <div class="upload-zone">
                        <div class="upload-icon">⬆️</div>
                        <p>Drag and drop your resume file here, or click to upload.</p>
                    </div>
                </div>
            `;
        }

        function renderFavoritesPage() {
            return `
                <div class="page-section">
                    <h2 class="section-title">❤️ Favorites</h2>
                    <p class="section-description">Saved templates and resume options for quick reuse</p>
                    <div class="empty-state">
                        <div class="empty-icon">💾</div>
                        <div class="empty-title">No favorites yet</div>
                        <p class="section-description">Mark templates as favorites to keep them here.</p>
                    </div>
                </div>
            `;
        }

        function attachMainListeners() {
            const logoutBtn = document.getElementById('logoutBtn');
            logoutBtn.addEventListener('click', () => {
                appState.isLoggedIn = false;
                appState.user = null;
                localStorage.removeItem('user');
                renderApp();
            });

            document.querySelectorAll('.nav-btn').forEach((button) => {
                button.addEventListener('click', () => {
                    document.querySelectorAll('.nav-btn').forEach((btn) => btn.classList.remove('active'));
                    button.classList.add('active');
                    appState.currentPage = button.dataset.page;
                    document.getElementById('mainContent').innerHTML = renderPageContent();
                });
            });

            document.querySelectorAll('.nav-btn[data-page="templates"]').forEach((button) => {
                button.addEventListener('click', () => {
                    document.getElementById('mainContent').innerHTML = renderPageContent();
                });
            });
        }

        function init() {
            const savedUser = localStorage.getItem('user');
            if (savedUser) {
                appState.isLoggedIn = true;
                appState.user = JSON.parse(savedUser);
            }
            renderApp();
        }

        init();
    </script>
</body>
</html>
