        { id: 109, name: 'Sales Leader', category: 'Sales', atsScore: 92, rating: 4.7, downloads: 1600, tags: ['Sales','Revenue','Customer'], description: 'High-converting resume for sales and business development.' },
        { id: 110, name: 'Human Resources', category: 'HR', atsScore: 88, rating: 4.4, downloads: 1240, tags: ['HR','Talent','People'], description: 'Polished resume for HR and talent acquisition roles.' },
        { id: 111, name: 'Customer Success', category: 'Customer', atsScore: 90, rating: 4.6, downloads: 1325, tags: ['Customer','Success','Support'], description: 'Professional resume for customer success and account roles.' },
        { id: 112, name: 'Remote Specialist', category: 'Remote', atsScore: 93, rating: 4.8, downloads: 1780, tags: ['Remote','Distributed','Agile'], description: 'Resume built for high-performing remote professionals.' }
      ],
