<body>
  <div id="root"></div>

  <script>
    const DB = {
      users: [
        { id: 1, email: 'admin@arj.com', password: '1234', name: 'Admin User' },
        { id: 2, email: 'user@arj.com', password: 'career', name: 'Career Seeker' }
      ],
      templates: [
        { id: 101, name: 'Executive Impact', category: 'Leadership', atsScore: 96, rating: 4.9, downloads: 2420, tags: ['C-Level','Strategy','Senior'], description: 'High-impact resume for executives and directors.' },
        { id: 102, name: 'Tech Innovator', category: 'Technology', atsScore: 94, rating: 4.8, downloads: 2180, tags: ['SaaS','Engineering','Product'], description: 'Clean and modern resume for tech roles.' },
        { id: 103, name: 'Data Specialist', category: 'Analytics', atsScore: 92, rating: 4.7, downloads: 1860, tags: ['Data','BI','ML'], description: 'ATS-friendly resume for data science and analytics.' },
        { id: 104, name: 'Marketing Maven', category: 'Marketing', atsScore: 93, rating: 4.7, downloads: 1700, tags: ['Brand','Growth','Digital'], description: 'Conversion-focused resume for marketing roles.' },
        { id: 105, name: 'Finance Pro', category: 'Finance', atsScore: 91, rating: 4.6, downloads: 1625, tags: ['Finance','Accounting','Audit'], description: 'Professional resume for finance and accounting jobs.' },
        { id: 106, name: 'Product Leader', category: 'Product', atsScore: 95, rating: 4.8, downloads: 1950, tags: ['Product','Roadmap','UX'], description: 'Structured resume for product management and leadership.' },
        { id: 107, name: 'UX Designer', category: 'Design', atsScore: 89, rating: 4.5, downloads: 1500, tags: ['Design','UX','Research'], description: 'Creative resume with visual hierarchy and ATS optimization.' },
        { id: 108, name: 'Operations Ace', category: 'Operations', atsScore: 90, rating: 4.5, downloads: 1380, tags: ['Operations','Project','Logistics'], description: 'Resume designed for operations and program roles.' },
        { id: 109, name: 'Sales Leader', category: 'Sales', atsScore: 92, rating: 4.7, downloads: 1600, tags: ['Sales','Revenue','Customer'], description: 'High-converting resume for sales and business development.' },
        { id: 110, name: 'Human Resources', category: 'HR', atsScore: 88, rating: 4.4, downloads: 1240, tags: ['HR','Talent','People'], description: 'Polished resume for HR and talent acquisition roles.' },
        { id: 111, name: 'Customer Success', category: 'Customer', atsScore: 90, rating: 4.6, downloads: 1325, tags: ['Customer','Success','Support'], description: 'Professional resume for customer success and account roles.' },
        { id: 112, name: 'Remote Specialist', category: 'Remote', atsScore: 93, rating: 4.8, downloads: 1780, tags: ['Remote','Distributed','Agile'], description: 'Resume built for high-performing remote professionals.' }
      ],
      reports: []
    };

    const state = {
      user: null,
      page: 'dashboard',
      lastMessage: '',
      notificationType: '',
      search: '',
      filterCategory: '',
      filterScore: '',
      sortBy: 'popular',
      favorites: [],
      compare: []
    };

    function saveAppState() {
      localStorage.setItem('arj_state', JSON.stringify({
        user: state.user,
        favorites: state.favorites,
        compare: state.compare
      }));
    }

    function loadAppState() {
      const saved = localStorage.getItem('arj_state');
      if (saved) {
        const parsed = JSON.parse(saved);
        state.user = parsed.user || null;
        state.favorites = parsed.favorites || [];
        state.compare = parsed.compare || [];
      }
    }

    function setNotification(message, type = 'info') {
      state.lastMessage = message;
      state.notificationType = type;
      render();
      setTimeout(() => {
        state.lastMessage = '';
        render();
      }, 2800);
    }

    function getTemplates() {
      let list = [...DB.templates];
      if (state.search) {
        const q = state.search.toLowerCase();
        list = list.filter(t => t.name.toLowerCase().includes(q) || t.description.toLowerCase().includes(q) || t.tags.some(tag => tag.toLowerCase().includes(q)));
      }
      if (state.filterCategory) {
        list = list.filter(t => t.category === state.filterCategory);
      }
      if (state.filterScore) {
        list = list.filter(t => t.atsScore >= Number(state.filterScore));
      }
      if (state.sortBy === 'ats_high') list.sort((a,b)=>b.atsScore-a.atsScore);
      else if (state.sortBy === 'ats_low') list.sort((a,b)=>a.atsScore-b.atsScore);
      else if (state.sortBy === 'rating') list.sort((a,b)=>b.rating-a.rating);
      else if (state.sortBy === 'downloads') list.sort((a,b)=>b.downloads-a.downloads);
      else list.sort((a,b)=>b.downloads-a.downloads);
      return list;
    }

    function toggleFavorite(templateId) {
      const index = state.favorites.indexOf(templateId);
      if (index === -1) state.favorites.push(templateId);
      else state.favorites.splice(index, 1);
      saveAppState();
      setNotification(index === -1 ? 'Added to favorites' : 'Removed from favorites', 'success');
    }

    function toggleCompare(templateId) {
      const index = state.compare.indexOf(templateId);
      if (index === -1) {
        if (state.compare.length >= 3) {
          setNotification('Compare works for up to 3 templates', 'error');
          return;
        }
        state.compare.push(templateId);
      } else {
        state.compare.splice(index, 1);
      }
      saveAppState();
      render();
    }

    function analyzeResume(text) {
      if (!text.trim()) return null;
      const keywords = ['team', 'project', 'data', 'results', 'leadership', 'strategy', 'automation', 'client', 'growth'];
      const found = keywords.filter(k => text.toLowerCase().includes(k));
      const score = Math.min(100, 55 + found.length * 5 + Math.floor(Math.random()*15));
      return {
        score,
        strengths: found.length ? found.slice(0,4) : ['Clear role alignment', 'Strong formatting'],
        improvements: found.length < 4 ? ['Add more keywords', 'Quantify achievements', 'Simplify bullet points'] : ['Add career metrics', 'Increase ATS keywords'],
        missingKeywords: keywords.filter(k => !found.includes(k)).slice(0, 5)
      };
    }

    function login(email, password) {
      const user = DB.users.find(u => u.email === email && u.password === password);
      if (!user) return false;
      state.user = { id: user.id, email: user.email, name: user.name };
      saveAppState();
      setNotification('Welcome back, ' + user.name, 'success');
      return true;
    }

    function register(email, password, name) {
      if (!email || !password || !name) return false;
      if (DB.users.find(u => u.email === email)) return false;
      const id = Date.now();
      DB.users.push({ id, email, password, name });
      state.user = { id, email, name };
      saveAppState();
      setNotification('Account created successfully', 'success');
      return true;
    }

    function logout() {
      state.user = null;
      state.page = 'dashboard';
      saveAppState();
      setNotification('Logged out successfully', 'info');
      render();
    }

    function getDashboardMetrics() {
      const templates = getTemplates();
      const avgAts = templates.reduce((sum,t)=>sum+t.atsScore,0)/templates.length;
      const roleMatch = Math.min(99, Math.round(avgAts + 2));
      const streak = Math.max(1, Math.floor(Math.random()*9));
      const apps = 18 + Math.floor(Math.random()*27);
      return { atsScore: Math.round(avgAts), roleMatch, streak, apps };
    }

    function renderLogin() {
      return `
        <div class="main">
          <div class="card" style="max-width: 520px; margin:auto;">
            <h1 style="font-size:2rem; margin-bottom:0.5rem;">ARJ Career AI</h1>
            <p class="muted" style="margin-bottom:1.75rem;">Sign in to open your career dashboard, resume templates, and analytics.</p>
            <label style="display:block; margin-bottom:12px;">Email<input id="login-email" class="input" placeholder="you@company.com" /></label>
            <label style="display:block; margin-bottom:12px;">Password<input id="login-password" type="password" class="input" placeholder="Password" /></label>
            <button id="login-action" class="button primary" style="width:100%; margin-bottom:12px;">Sign In</button>
            <button id="register-action" class="button secondary" style="width:100%;">Create Account</button>
            <p class="muted" style="margin-top:16px;">Use admin@arj.com / 1234 or any new account.</p>
          </div>
        </div>
      `;
    }

    function renderHeader() {
      return `
        <header>
          <div class="logo"><span>AI</span><div>ARJ Career AI</div></div>
          <div style="display: flex; gap: 12px; align-items:center;">
            <div class="muted">Hi, ${state.user.name}</div>
            <button id="logout-btn" class="button secondary">Logout</button>
          </div>
        </header>
        <div class="nav">
          ${['dashboard','templates','analyzer','favorites'].map(page => `
            <button class="${state.page===page?'active':''}" data-page="${page}">
              ${page==='dashboard'?'Dashboard':page==='templates'?'Templates':page==='analyzer'?'ATS Analyzer':'Favorites'}
            </button>
          `).join('')}
        </div>
      `;
    }

    function renderDashboard() {
      const metrics = getDashboardMetrics();
      return `
        <div class="main">
          <div class="hero">
            <div class="card">
              <h2>Welcome back, ${state.user.name}</h2>
              <p class="muted">Track resume performance, review top templates, and prepare for interviews.</p>
            </div>
            <div class="card notice">
              <strong>Mobile-ready</strong><br />
              This file contains frontend, backend logic, and dataset in one package.
            </div>
          </div>

          <div class="grid3">
            <div class="card">
              <div class="muted">Average ATS Score</div>
              <div class="metric">${metrics.atsScore}%</div>
            </div>
            <div class="card">
              <div class="muted">Role Match</div>
              <div class="metric">${metrics.roleMatch}%</div>
            </div>
            <div class="card">
              <div class="muted">Mock Streak</div>
              <div class="metric">${metrics.streak}d</div>
            </div>
          </div>

          <div class="grid2" style="margin-top:18px;">
            <div class="card">
              <h3>Fast Resume Templates</h3>
              <p class="muted">Browse templates designed for ATS, leadership, product, marketing, and remote roles.</p>
              <div class="row" style="margin-top:16px;">
                <button class="button primary" data-page="templates">View Templates</button>
                <button class="button secondary" data-page="analyzer">Analyze Resume</button>
              </div>
            </div>
            <div class="card">
              <h3>Saved Favorites</h3>
              <p class="muted">${state.favorites.length} saved templates.</p>
              <div class="row" style="margin-top:16px;">
                <button class="button primary" data-page="favorites">Open Favorites</button>
              </div>
            </div>
          </div>
        </div>
      `;
    }

    function renderTemplates() {
      const list = getTemplates();
      return `
        <div class="main">
          <div class="grid2">
            <div class="card">
              <h2>Template Library</h2>
              <p class="muted">Filter, sort, and choose the resume layout that fits your career.</p>
            </div>
            <div class="card">
              <label>Search<input id="search-text" class="input" value="${state.search}" placeholder="Keyword, role, tag" /></label>
              <div class="row" style="margin-top:12px;">
                <select id="filter-category" class="select">
                  <option value="">All Industries</option>
                  ${['Leadership','Technology','Analytics','Marketing','Finance','Product','Design','Operations','Sales','HR','Customer','Remote']
                    .map(c => `<option value="${c}" ${state.filterCategory===c?'selected':''}>${c}</option>`).join('')}
                </select>
                <select id="filter-score" class="select">
                  <option value="">Min ATS</option>
                  <option value="90" ${state.filterScore==='90'?'selected':''}>90+</option>
                  <option value="92" ${state.filterScore==='92'?'selected':''}>92+</option>
                  <option value="94" ${state.filterScore==='94'?'selected':''}>94+</option>
                </select>
              </div>
              <div class="row" style="margin-top:12px;">
                <select id="sort-by" class="select">
                  <option value="popular" ${state.sortBy==='popular'?'selected':''}>Most Downloaded</option>
                  <option value="ats_high" ${state.sortBy==='ats_high'?'selected':''}>ATS High→Low</option>
                  <option value="ats_low" ${state.sortBy==='ats_low'?'selected':''}>ATS Low→High</option>
                  <option value="rating" ${state.sortBy==='rating'?'selected':''}>Top Rated</option>
                </select>
                <button id="clear-filters" class="button secondary">Clear</button>
              </div>
            </div>
          </div>

          <div class="grid2" style="margin-top:18px;">
            ${list.map(template => `
              <div class="card template-card">
                <div class="template-banner">
                  <strong>${template.name}</strong>
                  <div style="margin-top:8px; opacity:.9;">${template.category} • ${template.atsScore}% ATS</div>
                </div>
                <div>
                  <p class="muted">${template.description}</p>
                  <div class="row" style="margin-top:12px;">
                    <span class="chip">⭐ ${template.rating}</span>
                    <span class="chip">📥 ${template.downloads}</span>
                  </div>
                  <div class="tags" style="margin-top:12px;">
                    ${template.tags.map(tag => `<span class="tag">${tag}</span>`).join('')}
                  </div>
                </div>
                <div class="row" style="margin-top:16px;">
                  <button class="button primary" data-action="favorite" data-id="${template.id}">
                    ${state.favorites.includes(template.id) ? '★ Saved' : '☆ Favorite'}
                  </button>
                  <button class="button secondary" data-action="compare" data-id="${template.id}">
                    ${state.compare.includes(template.id) ? '✔ Compare' : 'Compare'}
                  </button>
                </div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    function renderAnalyzer() {
      return `
        <div class="main">
          <div class="card">
            <h2>ATS Resume Analyzer</h2>
            <p class="muted">Paste your resume text below and run a quick analysis.</p>
            <textarea id="resume-text" class="textarea" placeholder="Paste resume text here..."></textarea>
            <div class="row" style="margin-top:14px;">
              <button id="analyze-btn" class="button primary">Analyze Resume</button>
              <button id="fill-sample" class="button secondary">Load Sample</button>
            </div>
          </div>
          <div id="analysis-result" class="card hide"></div>
        </div>
      `;
    }

    function renderFavorites() {
      const favorites = DB.templates.filter(t => state.favorites.includes(t.id));
      return `
        <div class="main">
          <div class="card">
            <h2>My Favorites</h2>
            <p class="muted">${favorites.length ? favorites.length + ' templates saved' : 'No favorites yet.'}</p>
          </div>
          <div class="grid2" style="margin-top:18px;">
            ${favorites.length ? favorites.map(template => `
              <div class="card template-card">
                <div class="template-banner">
                  <strong>${template.name}</strong>
                  <div style="margin-top:8px; opacity:.9;">${template.category} • ${template.atsScore}% ATS</div>
                </div>
                <div>
                  <p class="muted">${template.description}</p>
                </div>
                <div class="row" style="margin-top:16px;">
                  <button class="button secondary" data-action="remove-favorite" data-id="${template.id}">Remove</button>
                  <button class="button primary" data-action="compare" data-id="${template.id}">
                    ${state.compare.includes(template.id) ? '✔ Compare' : 'Compare'}
                  </button>
                </div>
              </div>
            `).join('') : `
              <div class="card">
                <p class="muted">Tap "Favorite" on a template to save it here.</p>
              </div>
            `}
          </div>
        </div>
      `;
    }

    function renderCompare() {
      if (!state.compare.length) return '';
      const list = DB.templates.filter(t => state.compare.includes(t.id));
      return `
        <div class="card" style="margin: 24px; padding:18px;">
          <h3>Compare (${list.length}/3)</h3>
          <div class="grid2" style="margin-top:14px;">
            ${list.map(t => `
              <div class="card">
                <strong>${t.name}</strong>
                <p class="muted">${t.category}</p>
                <div class="row" style="gap:10px; margin-top:10px;">ATS ${t.atsScore}%</div>
                <div class="row" style="gap:10px; margin-top:6px;">⭐ ${t.rating} • 📥 ${t.downloads}</div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }

    function render() {
      const root = document.getElementById('root');
      if (!state.user) {
        root.innerHTML = renderLogin();
        document.getElementById('login-action').onclick = () => {
          const email = document.getElementById('login-email').value.trim();
          const password = document.getElementById('login-password').value.trim();
          if (!login(email, password)) setNotification('Invalid email or password', 'error');
          else { state.page = 'dashboard'; render(); }
        };
        document.getElementById('register-action').onclick = () => {
          const email = document.getElementById('login-email').value.trim();
          const password = document.getElementById('login-password').value.trim();
          const name = email.split('@')[0] || 'Guest';
          if (!register(email, password, name)) setNotification('Unable to register, email exists or missing fields', 'error');
          else { state.page = 'dashboard'; render(); }
        };
        return;
      }

      root.innerHTML = `${renderHeader()}${state.page === 'dashboard' ? renderDashboard() : state.page === 'templates' ? renderTemplates() : state.page === 'analyzer' ? renderAnalyzer() : renderFavorites() }${state.compare.length ? renderCompare() : ''}${state.lastMessage ? `<div class="footer ${state.notificationType==='error'?'error':''}">${state.lastMessage}</div>` : '<div class="footer">App running fully offline in one file.</div>'}`;
      document.querySelectorAll('.nav button').forEach(btn => {
        btn.onclick = () => { state.page = btn.dataset.page; render(); };
      });
      document.getElementById('logout-btn').onclick = logout;

      if (state.page === 'templates') {
        document.getElementById('search-text').oninput = e => { state.search = e.target.value; render(); };
        document.getElementById('filter-category').onchange = e => { state.filterCategory = e.target.value; render(); };
        document.getElementById('filter-score').onchange = e => { state.filterScore = e.target.value; render(); };
        document.getElementById('sort-by').onchange = e => { state.sortBy = e.target.value; render(); };
        document.getElementById('clear-filters').onclick = () => { state.search = ''; state.filterCategory = ''; state.filterScore = ''; state.sortBy='popular'; render(); };
        document.querySelectorAll('[data-action="favorite"]').forEach(btn => {
          btn.onclick = () => { toggleFavorite(Number(btn.dataset.id)); render(); };
        });
        document.querySelectorAll('[data-action="compare"]').forEach(btn => {
          btn.onclick = () => { toggleCompare(Number(btn.dataset.id)); render(); };
        });
      }

      if (state.page === 'favorites') {
        document.querySelectorAll('[data-action="remove-favorite"]').forEach(btn => {
          btn.onclick = () => { toggleFavorite(Number(btn.dataset.id)); render(); };
        });
        document.querySelectorAll('[data-action="compare"]').forEach(btn => {
          btn.onclick = () => { toggleCompare(Number(btn.dataset.id)); render(); };
        });
      }

      if (state.page === 'analyzer') {
        document.getElementById('analyze-btn').onclick = () => {
          const text = document.getElementById('resume-text').value.trim();
          const result = analyzeResume(text);
          const box = document.getElementById('analysis-result');
          if (!result) { box.classList.remove('hide'); box.innerHTML = '<p class="error">Paste resume text first.</p>'; return; }
          box.classList.remove('hide');
          box.innerHTML = `
            <h3>Analysis Result</h3>
            <p class="muted">Score ${result.score}%</p>
            <div class="row" style="gap:10px; margin-top:12px;">
              <div class="chip">Strengths: ${result.strengths.join(', ')}</div>
              <div class="chip">Missing: ${result.missingKeywords.join(', ')}</div>
            </div>
            <p style="margin-top:12px;">${result.improvements.join(' • ')}</p>
          `;
        };
        document.getElementById('fill-sample').onclick = () => {
          document.getElementById('resume-text').value = 'Experienced product leader with strong project management, team collaboration, data-driven results and customer growth.';
        };
      }
    }

    loadAppState();
    render();
  </script>
</body>
</html>
